"use client";

import { motion } from "framer-motion";
import { SectionHeading } from "@/components/ui/section-heading";
import { Card } from "@/components/ui/card";
import { Award } from "lucide-react";

const certificates = [
    "Diploma in Computer Application (DCA) - CSC",
    "Paper Presentation Certificate - IEEE Conference",
    "2-day IoT Workshop - Senstorent",
    "AI Fluency for Students - Anthropic",
    "Paper Presentation Certificate - National Conference"
];

export function Certificates() {
    return (
        <section id="certificates" className="py-24 px-4 sm:px-6 lg:px-8">
            <div className="mx-auto max-w-4xl">
                <SectionHeading title="Certificates & Training" subtitle="Continuous learning and professional development." />

                <div className="grid gap-4 sm:grid-cols-2 lg:grid-cols-3">
                    {certificates.map((cert, index) => (
                        <motion.div
                            key={index}
                            initial={{ opacity: 0, scale: 0.9 }}
                            whileInView={{ opacity: 1, scale: 1 }}
                            viewport={{ once: true }}
                            transition={{ delay: index * 0.1 }}
                        >
                            <Card className="flex h-full flex-col items-center p-6 text-center hover:border-blue-500/50">
                                <Award className="mb-4 h-8 w-8 text-blue-500" />
                                <p className="font-medium text-neutral-200">{cert}</p>
                            </Card>
                        </motion.div>
                    ))}
                </div>
            </div>
        </section>
    );
}
